const video = document.querySelector('video');
const r = video.getBoundingClientRect();
const scaleX = r.width / video.videoWidth;
const scaleY = r.height / video.videoHeight;

let dbg = document.getElementById('dbg-overlay');
if (dbg) dbg.remove();
dbg = document.createElement('canvas');
dbg.id = 'dbg-overlay';
dbg.width = r.width;
dbg.height = r.height;
dbg.style.position = 'fixed';
dbg.style.left = r.x + 'px';
dbg.style.top = r.y + 'px';
dbg.style.zIndex = 99999;
dbg.style.pointerEvents = 'none';
document.body.appendChild(dbg);
const ctx = dbg.getContext('2d');

const boxes = [
  { corner: 0, x1: 485.1546630859375, y1: 133.66192626953125, x2: 924.6904296875, y2: 601.0369873046875, color: 'red' },
  { corner: 1, x1: 437.7392883300781, y1: 114.2467041015625, x2: 648.801025390625, y2: 583.4486083984375, color: 'lime' },
];
for (const b of boxes) {
  ctx.strokeStyle = b.color;
  ctx.lineWidth = 4;
  ctx.strokeRect(b.x1 * scaleX, b.y1 * scaleY, (b.x2 - b.x1) * scaleX, (b.y2 - b.y1) * scaleY);
  ctx.font = 'bold 22px sans-serif';
  ctx.fillStyle = b.color;
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.strokeText('corner=' + b.corner, b.x1 * scaleX + 4, b.y1 * scaleY + 24);
  ctx.fillText('corner=' + b.corner, b.x1 * scaleX + 4, b.y1 * scaleY + 24);
}
'drawn';

